// Generated by bloom (`bloom build android`): `expo-video` in a Bloom build, over Bloom's own
// native player (the standard library's `extern native "BloomVideo"`, androidx media3).
// `useVideoPlayer`, `createVideoPlayer`, `VideoView` and the player's properties, methods and
// events keep expo-video's API, so an app's call sites need no edits.
//
// A player is a number this file picks; the native module holds an ExoPlayer under it. The
// player's state (status, playing, time, duration, picture size) arrives as the module's
// events and is kept here, so a property read never crosses to native.

const React = require('react');
const { Image, TurboModuleRegistry } = require('react-native');

let native;
function bloomVideo() {
  if (native === undefined) native = TurboModuleRegistry.get('BloomVideo');
  if (!native) throw new Error('expo-video: this build has no BloomVideo module');
  return native;
}

const players = new Map();
let nextId = 1;
let subscribed = false;

function subscribe() {
  if (subscribed) return;
  subscribed = true;
  const m = bloomVideo();
  const to = (event) => (e) => players.get(e.player)?._native(event, e);
  m.onStatus(to('status'));
  m.onPlaying(to('playing'));
  m.onTime(to('time'));
  m.onEnd(to('end'));
  m.onSource(to('source'));
}

/** A source as expo-video takes it: a URL, a bundled asset, `{ uri, headers }`, or nothing. */
function resolve(source) {
  if (source == null) return { uri: null, headers: [], source: null };
  if (typeof source === 'string') return { uri: source, headers: [], source: { uri: source } };
  if (typeof source === 'number') {
    const asset = Image.resolveAssetSource(source);
    return { uri: asset?.uri ?? null, headers: [], source: { assetId: source } };
  }
  const uri =
    source.uri ??
    (typeof source.assetId === 'number' ? Image.resolveAssetSource(source.assetId)?.uri : null);
  const headers = source.headers
    ? Object.entries(source.headers).flatMap(([k, v]) => [k, String(v)])
    : [];
  return { uri: uri ?? null, headers, source };
}

class VideoPlayer {
  constructor(source) {
    subscribe();
    this._id = nextId++;
    this._listeners = new Map();
    this._status = 'idle';
    this._playing = false;
    this._muted = false;
    this._loop = false;
    this._volume = 1;
    this._rate = 1;
    this._time = 0;
    this._buffered = 0;
    this._duration = 0;
    this._size = null;
    this._interval = 0;
    this._released = false;
    const { uri, headers, source: resolved } = resolve(source);
    this._source = resolved;
    players.set(this._id, this);
    bloomVideo().create(this._id, uri, headers);
    // Stored only: what expo-video's options a Bloom build does not act on yet.
    this.bufferOptions = {
      preferredForwardBufferDuration: 0,
      minBufferForPlayback: 2,
      waitsToMinimizeStalling: true,
    };
    this.allowsExternalPlayback = false;
    this.staysActiveInBackground = false;
    this.showNowPlayingNotification = false;
    this.keepScreenOnWhilePlaying = true;
    this.preservesPitch = true;
    this.audioMixingMode = 'auto';
    this.subtitleTrack = null;
    this.audioTrack = null;
    this.availableSubtitleTracks = [];
    this.availableAudioTracks = [];
  }

  get playing() {
    return this._playing;
  }
  get status() {
    return this._status;
  }
  get duration() {
    return this._duration;
  }
  get bufferedPosition() {
    return this._buffered;
  }
  get isLive() {
    return false;
  }
  get currentLiveTimestamp() {
    return null;
  }
  get currentOffsetFromLive() {
    return null;
  }
  get videoTrack() {
    return this._size ? { size: this._size, id: '0', isSupported: true } : null;
  }
  get availableVideoTracks() {
    return this._size ? [this.videoTrack] : [];
  }

  get currentTime() {
    return this._time;
  }
  set currentTime(seconds) {
    this._time = seconds;
    bloomVideo().seek(this._id, seconds);
  }

  get muted() {
    return this._muted;
  }
  set muted(value) {
    if (this._muted === !!value) return;
    this._muted = !!value;
    bloomVideo().setMuted(this._id, this._muted);
    this.emit('mutedChange', { muted: this._muted, oldMuted: !this._muted });
  }

  get loop() {
    return this._loop;
  }
  set loop(value) {
    this._loop = !!value;
    bloomVideo().setLoop(this._id, this._loop);
  }

  get volume() {
    return this._volume;
  }
  set volume(value) {
    const old = this._volume;
    this._volume = value;
    bloomVideo().setVolume(this._id, value);
    this.emit('volumeChange', { volume: value, oldVolume: old });
  }

  get playbackRate() {
    return this._rate;
  }
  set playbackRate(value) {
    const old = this._rate;
    this._rate = value;
    bloomVideo().setRate(this._id, value);
    this.emit('playbackRateChange', { playbackRate: value, oldPlaybackRate: old });
  }

  get timeUpdateEventInterval() {
    return this._interval;
  }
  set timeUpdateEventInterval(seconds) {
    this._interval = seconds;
    bloomVideo().setTimeInterval(this._id, seconds);
  }

  play() {
    if (!this._released) bloomVideo().play(this._id);
  }
  pause() {
    if (!this._released) bloomVideo().pause(this._id);
  }
  seekBy(seconds) {
    this.currentTime = Math.max(0, this._time + seconds);
  }
  replay() {
    this.currentTime = 0;
    this.play();
  }

  replace(source) {
    const old = this._source;
    const { uri, headers, source: resolved } = resolve(source);
    this._source = resolved;
    this._duration = 0;
    this._time = 0;
    bloomVideo().replace(this._id, uri, headers);
    this.emit('sourceChange', { source: resolved, oldSource: old });
  }

  replaceAsync(source) {
    this.replace(source);
    return Promise.resolve();
  }

  generateThumbnailsAsync() {
    return Promise.resolve([]);
  }

  release() {
    if (this._released) return;
    this._released = true;
    players.delete(this._id);
    bloomVideo().release(this._id);
    this._listeners.clear();
  }

  addListener(event, listener) {
    let set = this._listeners.get(event);
    if (!set) {
      set = new Set();
      this._listeners.set(event, set);
    }
    set.add(listener);
    return { remove: () => set.delete(listener) };
  }

  removeListener(event, listener) {
    this._listeners.get(event)?.delete(listener);
  }
  removeAllListeners(event) {
    this._listeners.delete(event);
  }
  listenerCount(event) {
    return this._listeners.get(event)?.size ?? 0;
  }

  emit(event, payload) {
    const set = this._listeners.get(event);
    if (set) for (const listener of [...set]) listener(payload);
  }

  /** An event of the native module about this player. */
  _native(event, e) {
    switch (event) {
      case 'status': {
        const old = this._status;
        this._status = e.status;
        const error = e.error ? { message: e.error } : undefined;
        if (old !== e.status || error)
          this.emit('statusChange', { status: e.status, oldStatus: old, error });
        break;
      }
      case 'playing':
        if (this._playing === e.playing) break;
        this._playing = e.playing;
        this.emit('playingChange', { isPlaying: e.playing, oldIsPlaying: !e.playing });
        break;
      case 'time':
        this._time = e.currentTime;
        this._buffered = e.buffered;
        this.emit('timeUpdate', {
          currentTime: e.currentTime,
          currentLiveTimestamp: null,
          currentOffsetFromLive: null,
          bufferedPosition: e.buffered,
        });
        break;
      case 'end':
        this.emit('playToEnd');
        break;
      case 'source': {
        const old = this.videoTrack;
        this._duration = e.duration;
        const size = e.width > 0 ? { width: e.width, height: e.height } : null;
        const changed =
          size &&
          (!this._size || size.width !== this._size.width || size.height !== this._size.height);
        this._size = size ?? this._size;
        this.emit('sourceLoad', {
          videoSource: this._source,
          duration: e.duration,
          availableVideoTracks: this.availableVideoTracks,
          availableSubtitleTracks: [],
          availableAudioTracks: [],
        });
        if (changed)
          this.emit('videoTrackChange', { videoTrack: this.videoTrack, oldVideoTrack: old });
        break;
      }
    }
  }
}

function createVideoPlayer(source) {
  return new VideoPlayer(source);
}

/** A player for `source`, made again when the source changes and released on unmount. */
function useVideoPlayer(source, setup) {
  const key = typeof source === 'object' && source !== null ? JSON.stringify(source) : source;
  const player = React.useMemo(() => {
    const made = new VideoPlayer(source);
    setup?.(made);
    return made;
  }, [key]);
  React.useEffect(() => () => player.release(), [player]);
  return player;
}

let NativeView;
function nativeView() {
  if (NativeView === undefined) {
    // The view's spec, generated beside the standard library (`.bloom/std`).
    NativeView = require('../../std/Bloom/BloomVideoViewNativeComponent').default;
  }
  return NativeView;
}

const VideoView = React.forwardRef(function VideoView(props, ref) {
  const { player, contentFit, onFirstFrameRender, nativeControls: _controls, ...rest } = props;
  React.useImperativeHandle(ref, () => ({
    enterFullscreen: () => Promise.resolve(),
    exitFullscreen: () => Promise.resolve(),
    startPictureInPicture: () => Promise.resolve(),
    stopPictureInPicture: () => Promise.resolve(),
  }));
  const View = nativeView();
  return React.createElement(View, {
    ...rest,
    player: player?._id ?? -1,
    contentFit: contentFit === 'cover' || contentFit === 'fill' ? contentFit : 'contain',
    onFirstFrame: onFirstFrameRender ? () => onFirstFrameRender() : undefined,
  });
});

module.exports = {
  VideoPlayer,
  VideoView,
  createVideoPlayer,
  useVideoPlayer,
  isPictureInPictureSupported: () => false,
  clearVideoCacheAsync: () => Promise.resolve(),
  setVideoCacheSizeAsync: () => Promise.resolve(),
  getCurrentVideoCacheSize: () => 0,
};
